WITH scored AS (SELECT *, LEAD(amount) OVER w_ordered AS next_amount, ROW_NUMBER() OVER w_ordered AS row_seq FROM payments WINDOW w_ordered AS (PARTITION BY status ORDER BY amount, id)), valid AS (SELECT *, UPPER(method) AS method_upper, DATEDIFF(CURRENT_DATE(), paid_at) / 365.25 AS years_since_paid_at FROM scored WHERE paid_at >= DATE '2023-10-20' AND status != 'REFUNDED'), joined AS (SELECT s.*, d.discount, d.shipping_fee FROM valid s LEFT JOIN orders d ON s.order_id = d.id WHERE d.store_id IS NULL), enriched AS (SELECT e.*, b.discount AS order_discount, b.order_date FROM joined e LEFT JOIN orders b ON e.order_id <=> b.id), metrics AS (SELECT id, status, next_amount, row_seq, method_upper, years_since_paid_at, discount, shipping_fee, order_date, NTILE(3) OVER (ORDER BY shipping_fee DESC, id) AS shipping_fee_bucket, ROUND(amount / SUM(amount) OVER (PARTITION BY status), 4) AS amount_share, LAG(order_discount, 1) OVER (PARTITION BY order_id ORDER BY order_discount, id) AS prev_order_discount, RANK() OVER (PARTITION BY MONTH(order_date), status ORDER BY shipping_fee DESC) AS shipping_fee_rank, FIRST_VALUE(order_discount, TRUE) OVER (PARTITION BY status ORDER BY years_since_paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_order_discount FROM enriched), stats AS (SELECT DATE_TRUNC('QUARTER', order_date) AS quarter_start, status, APPROX_PERCENTILE(first_known_order_discount, 0.9) AS first_known_order_discount_p90, ROUND(SUM(first_known_order_discount) / NULLIF(COUNT(CASE WHEN status = 'SUCCESS' THEN 1 END), 0), 2) AS first_known_order_discount_per_success, SUM(CASE WHEN status = 'REFUNDED' THEN next_amount ELSE 0 END) AS refunded_next_amount, PERCENTILE_APPROX(shipping_fee, 0.5) AS shipping_fee_p50 FROM metrics GROUP BY DATE_TRUNC('QUARTER', order_date), status HAVING first_known_order_discount_p90 > 0) SELECT quarter_start, status, first_known_order_discount_per_success, shipping_fee_p50 FROM stats ORDER BY status NULLS FIRST
